<script setup lang="ts">
import {ref,onMounted} from 'vue'
import PortalAccess from './PortalAccess.vue'
import AssuranceContacts from './AssuranceContacts.vue'
import AssuranceAssignments from './AssuranceAssignments.vue'
import AssuranceAppointments from './AssuranceAppointments.vue'
import AssuranceFollowUps from './AssuranceFollowUps.vue'
import {ShieldCheck,ArrowRight,Layers,LogOut,Users,Home,RefreshCw} from 'lucide-vue-next'
type Membership={workspace:string;role:string}
const user=ref<{username:string;workspaces:Membership[];admin_workspaces:string[];landing:string|null}|null>(null)
const workspace=ref(''),username=ref(''),password=ref(''),error=ref(''),busy=ref(false),ready=ref(false)
const managing=ref(false),assuranceModule=ref('contacts')
const summary=ref<any>(null)
let csrf=''
async function portal(path:string,body?:any,method?:string){
 if(body!==undefined&&!csrf){const response=await fetch('/api/portal/csrf/',{credentials:'include'});csrf=(await response.json()).csrfToken}
 const response=await fetch('/api/portal/'+path,{method:method||(body!==undefined?'POST':'GET'),credentials:'include',headers:{'Content-Type':'application/json',...(csrf?{'X-CSRFToken':csrf}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{})})
 if(!response.ok){const result=await response.json().catch(()=>({}));throw new Error(result.detail||Object.entries(result).map(([key,value])=>key+': '+String(value)).join(' · ')||'Accès indisponible')}
 return response.status===204?null:response.json()
}
async function business(path:string,body?:any,method?:string,target=workspace.value){
 const grant=await portal('access/'+target+'/',{})
 const response=await fetch('/api/'+target+'/'+path,{method:method||(body!==undefined?'POST':'GET'),headers:{Authorization:'Bearer '+grant.token,...(body instanceof FormData?{}:{'Content-Type':'application/json'})},...(body!==undefined?{body:body instanceof FormData?body:JSON.stringify(body)}:{})})
 if(!response.ok){const result=await response.json().catch(()=>({}));const failure=new Error(result.detail||(Array.isArray(result)?result.join(' · '):Object.values(result).join(' · '))||'Service métier indisponible') as Error & {status:number};failure.status=response.status;throw failure}
 return response.status===204?null:response.json()
}
function assurance(path:string,body?:any,method?:string){return business(path,body,method,'assurance')}
async function enter(value:string){
 error.value='';busy.value=true;workspace.value=value;assuranceModule.value='contacts'
 try{summary.value=await business('dashboard/')}
 catch(e:any){error.value=e.message;summary.value=null}finally{busy.value=false}
}
async function login(){
 busy.value=true;error.value=''
 try{user.value=await portal('login/',{username:username.value,password:password.value});password.value='';csrf='';if(user.value?.landing)await enter(user.value.landing)}
 catch(e:any){error.value=e.message}finally{busy.value=false}
}
async function logout(){await portal('session/',{});user.value=null;workspace.value='';summary.value=null;csrf=''}

const title=(value:string)=>value==='assurance'?'Assurance':'Isolation'
onMounted(async()=>{try{user.value=await portal('session/');if(user.value?.landing)await enter(user.value.landing)}catch{}finally{ready.value=true}})
</script>
<template>
 <div class="amx-root"><header class="amx-header"><a href="/crm" class="amx-brand"><Layers :size="26"/>AMX<span>CRM</span></a><span class="amx-header-note">Assurance & Isolation</span><button v-if="user" class="secondary" @click="logout"><LogOut :size="16"/>Déconnexion</button></header>
 <main class="amx-main"><p v-if="!ready" class="subtle">Chargement de votre espace…</p><p v-if="error" role="alert" class="error">{{error}}</p>
 <section v-if="ready&&!user" class="amx-login"><div class="amx-symbol"><ShieldCheck :size="30"/></div><p class="amx-eyebrow">VOTRE ESPACE DE TRAVAIL</p><h1>Bienvenue sur AMX.</h1><p class="subtle">Connectez-vous pour retrouver vos espaces autorisés.</p><form @submit.prevent="login"><label>Identifiant<input v-model="username" autocomplete="username" required></label><label>Mot de passe<input v-model="password" type="password" autocomplete="current-password" required></label><button class="primary full-width" :disabled="busy">{{busy?'Connexion…':'Se connecter'}}<ArrowRight :size="18"/></button></form><p class="amx-footnote">Portail de développement · Les intégrations métier sont ajoutées progressivement.</p></section>
 <template v-else-if="user"><button v-if="user.admin_workspaces?.length" class="secondary" @click="managing=!managing">{{managing?"Retour aux espaces":"Utilisateurs et accès"}}</button><PortalAccess v-if="managing" :spaces="user.admin_workspaces" :username="user.username" :request="portal"/><template v-else><div class="amx-heading"><div><p class="amx-eyebrow">VOTRE ESPACE DE TRAVAIL</p><h1>{{workspace?title(workspace):'Bonjour, '+user.username}}</h1><p class="subtle">{{workspace?'Vos accès et données sont propres à cet espace.':'Choisissez votre espace pour commencer.'}}</p></div><button v-if="workspace&&user.workspaces.length>1" class="secondary" @click="workspace='';summary=null"><Layers :size="17"/>Changer d’espace</button></div>
 <div v-if="!workspace" class="amx-spaces"><button v-for="item in user.workspaces" :key="item.workspace" class="amx-space" @click="enter(item.workspace)"><span class="amx-space-icon"><ShieldCheck v-if="item.workspace==='assurance'" :size="27"/><Home v-else :size="27"/></span><h2>{{title(item.workspace)}}</h2><p>{{item.workspace==='assurance'?'Contacts, conseillers et suivi des rendez-vous.':'Qualification des prospects et suivi des visites.'}}</p><span class="amx-role">{{({administrator:'Administrateur',setter:'Setter',advisor:'Conseiller',client:'Client'} as Record<string,string>)[item.role]||item.role}}</span><span class="amx-open">Ouvrir l’espace <ArrowRight :size="18"/></span></button></div><p v-if="!user.workspaces.length" class="panel-note">Aucun espace ne vous est encore attribué. Contactez votre administrateur.</p>
 <section v-if="workspace" class="card amx-workspace"><div class="card-header"><h2>{{workspace==='assurance'?'Contacts Assurance':'Qualification Isolation'}}</h2><button class="icon-button" aria-label="Actualiser l’espace" @click="enter(workspace)"><RefreshCw :size="18"/></button></div><div class="amx-content"><p v-if="busy">Chargement…</p><template v-if="summary"><div class="amx-count"><Users :size="22"/><strong>{{workspace==='assurance'?summary.contacts:summary.unique_numbers}}</strong><span>contacts dans cet espace</span></div><p class="panel-note">Socle en cours de construction. Les modules Phonetico, agendas, rendez-vous et tâches seront livrés dans les prochains lots.</p><template v-if="workspace==='assurance'"><p v-if="summary.open_follow_ups" role="status">{{summary.open_follow_ups}} tâche(s) de suivi à traiter. <button class="secondary" @click="assuranceModule='followups'">Ouvrir les tâches</button></p><p v-if="summary.reports_due" role="status">{{summary.reports_due}} compte(s) rendu(s) à fournir.</p><nav class="assignment-actions" aria-label="Modules Assurance"><button class="secondary" @click="assuranceModule='contacts'">Contacts</button><button v-if="summary.role!=='advisor'" class="secondary" @click="assuranceModule='assignments'">{{summary.role==='administrator'?'Affectations des conseillers':'Mes conseillers'}}</button><button class="secondary" @click="assuranceModule='appointments'">Rendez-vous</button><button v-if="summary.role!=='advisor'" class="secondary" @click="assuranceModule='followups'">Tâches de suivi</button></nav><AssuranceContacts v-if="assuranceModule==='contacts'" :portal="portal" :request="assurance" :role="summary.role" @imported="summary.contacts=$event"/><AssuranceAssignments v-else-if="assuranceModule==='assignments'&&summary.role!=='advisor'" :request="assurance" :portal="portal" :role="summary.role"/><AssuranceFollowUps :role="summary.role" v-else-if="assuranceModule==='followups'&&summary.role!=='advisor'" :request="assurance"/><AssuranceAppointments v-else :request="assurance" :portal="portal" :role="summary.role"/></template><template v-else><p>Les imports, la qualification Lookup et les exports existants restent disponibles dans l’application historique pendant la transition.</p><a class="secondary" href="/">Ouvrir CallVerify existant <ArrowRight :size="16"/></a><small class="subtle">Une session historique distincte reste nécessaire pour ce parcours.</small></template></template></div></section>
 </template></template></main><footer class="amx-footer">AMX · Un accès commun, des espaces métier distincts.</footer></div>
</template>
<style>
.amx-root{min-height:100vh;background:#f6f5ed;color:#20271e}.amx-header{height:86px;display:flex;align-items:center;gap:25px;border-bottom:1px solid #e6e5d9;padding:0 6vw}.amx-brand{display:flex;gap:10px;align-items:center;font-size:26px;font-weight:800;color:#303d20;text-decoration:none}.amx-brand span{font-size:12px;letter-spacing:2px;color:#7c806d}.amx-header-note{color:#7c806d;font-size:13px;flex:1}.amx-main{max-width:1100px;margin:auto;padding:64px 28px;min-height:calc(100vh - 150px)}.amx-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:40px}.amx-heading h1,.amx-login h1{font-size:38px;letter-spacing:-1.3px;margin:10px 0 15px}.amx-eyebrow{color:#777f65;font-size:11px;font-weight:700;letter-spacing:1.8px}.amx-spaces{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:26px}.amx-space{padding:35px;text-align:left;background:#fffefa;border:1px solid #e0e2d2;border-radius:22px;cursor:pointer;color:inherit;box-shadow:0 8px 24px #43551e05}.amx-space:hover{border-color:#8c9c63;box-shadow:0 10px 30px #43551e10}.amx-space h2{font-size:27px;margin:22px 0 12px}.amx-space p{color:#767d68;line-height:1.7;min-height:50px}.amx-space-icon,.amx-symbol{display:inline-flex;padding:15px;background:#edefde;border-radius:15px;color:#53661c}.amx-space:nth-child(2) .amx-space-icon{background:#eeeafa;color:#7965a7}.amx-role{display:inline-block;background:#f2f2e8;padding:6px 10px;border-radius:8px;font-size:12px}.amx-open{display:flex;align-items:center;justify-content:space-between;margin-top:30px;color:#53661c;font-weight:700}.amx-login{max-width:420px;margin:15px auto}.amx-login form{display:grid;gap:22px;margin-top:32px}.amx-root label{display:grid;gap:9px;font-size:13px;font-weight:600}.amx-root input{padding:13px 15px;border:1px solid #dedfce;border-radius:11px;background:#fff;width:100%;color:#20271e}.amx-footnote,.amx-footer{font-size:12px;color:#868c77;line-height:1.7}.amx-footnote{margin-top:25px}.amx-footer{text-align:center;padding:16px}.amx-content{padding:28px}.amx-count{display:flex;gap:15px;align-items:center}.amx-count strong{font-size:32px}.amx-count span{color:#777f65}.amx-contact-form{display:grid;grid-template-columns:1fr 1fr auto;gap:18px;align-items:end;margin:30px 0}.amx-content small{display:block;margin-top:12px}@media(max-width:650px){.amx-spaces{grid-template-columns:1fr}.amx-header-note{display:none}.amx-header{justify-content:space-between;padding:0 20px}.amx-heading{align-items:start;flex-direction:column}.amx-main{padding:35px 20px}.amx-contact-form{grid-template-columns:1fr}.amx-space{padding:25px}}
</style>
